    {"control_id": "Art.7", "title": "Conditions for consent", "category": "Lawfulness of Processing", "description": "Controller shall be able to demonstrate that data subject has consented"},
    {"control_id": "Art.8", "title": "Conditions for child's consent", "category": "Lawfulness of Processing", "description": "Child's consent valid at age 16 or with parental responsibility"},
    {"control_id": "Art.9", "title": "Processing of special categories of personal data", "category": "Special Categories", "description": "Processing of sensitive data (health, biometric, genetic, race, etc.) prohibited unless exception applies"},
    {"control_id": "Art.12", "title": "Transparent information and communication", "category": "Rights of Data Subject", "description": "Provide information in concise, transparent, intelligible and easily accessible form"},
    {"control_id": "Art.13", "title": "Information to be provided where personal data collected", "category": "Rights of Data Subject", "description": "Identity of controller, purposes of processing, legal basis, recipients, retention period"},
    {"control_id": "Art.15", "title": "Right of access by the data subject", "category": "Rights of Data Subject", "description": "Data subject shall have right to obtain confirmation of processing and access to data"},
    {"control_id": "Art.16", "title": "Right to rectification", "category": "Rights of Data Subject", "description": "Data subject shall have right to rectification of inaccurate personal data"},
    {"control_id": "Art.17", "title": "Right to erasure (right to be forgotten)", "category": "Rights of Data Subject", "description": "Data subject shall have right to erasure of personal data without undue delay"},
