    {"control_id": "Art.20", "title": "Right to data portability", "category": "Rights of Data Subject", "description": "Right to receive personal data in structured, commonly used and machine-readable format"},
    {"control_id": "Art.21", "title": "Right to object", "category": "Rights of Data Subject", "description": "Right to object to processing including profiling"},
    {"control_id": "Art.22", "title": "Automated individual decision-making", "category": "Rights of Data Subject", "description": "Right not to be subject to decision based solely on automated processing"},
    {"control_id": "Art.25", "title": "Data protection by design and by default", "category": "Controller and Processor", "description": "Implement appropriate technical and organisational measures"},
    {"control_id": "Art.28", "title": "Processor", "category": "Controller and Processor", "description": "Processing by processor shall be governed by contract"},
    {"control_id": "Art.30", "title": "Records of processing activities", "category": "Controller and Processor", "description": "Maintain record of processing activities under its responsibility"},
