def get_framework_controls(framework_name):
    """Return controls for a specific framework"""
    mapping = {
        "NIST Cybersecurity Framework": NIST_CSF_CONTROLS,
        "NIST AI Risk Management Framework": NIST_AI_RMF_CONTROLS,
        "Financial Services AI Risk Management Framework": FINANCIAL_SERVICES_AI_RMF_CONTROLS,
        "ISO 27001": ISO_27001_CONTROLS,
        "NIST SP 800-53": NIST_800_53_CONTROLS,
        "GDPR": GDPR_CONTROLS,
        "HIPAA": HIPAA_CONTROLS,
        "SOC 2": SOC2_CONTROLS,
        "CMMC": CMMC_CONTROLS,
        "NIS2": NIS2_CONTROLS,
        "NIST SP 800-171": NIST_800_171_CONTROLS,
        "StateRAMP": STATERAMP_CONTROLS
    }
    return mapping.get(framework_name, [])
